import { Link } from "react-router-dom";
import Teachersidebar from "./Teachersidebar";
import { useState,useEffect } from "react";
import {Routes as Switch, Route} from 'react-router-dom';
import axios from "axios";
function Addcourse(){
    const[cats,setCats]=useState([]);
    const [courseData,setCourseData]=useState({
        "category":'',
        "title":'',
        "description":'',
        "featured_image":null,
        "techs":''
    });
    useEffect(()=>{
        try{
            axios.get("http://127.0.0.1:8000/api/category/").then((response)=>{
                setCats(response.data);
                console.log(response.data);
            })
        }catch(error){
            console.log(error);
        }},[])  
    const handleChange=(event)=>{
        setCourseData({
            ...courseData,
            [event.target.name]:event.target.value
        });
    }
    const handleFileChange=(event)=>{
        setCourseData({
            ...courseData,
            [event.target.name]:event.target.files[0]
        });
    } 
    const submitForm=(event)=>{
        event.preventDefault();
        const courseFormData=new FormData();    
        formData.append("category",courseData.category);
        formData.append("title",courseData.title);
        formData.append("description",courseData.description);  
        formData.append("featured_image",courseData.featured_image,courseData.featured_image.name);
        formData.append("techs",courseData.techs); 
        try{
            axios.post("http://127://0.0.1:8000/api/course/",courseFormData,{
                headers:{
                    'content-type':'multipart/form-data'
                }
            }).then((response)=>{
                //console.log(response.data);
                window.location.href="/teacher-mycourses"
            });}
            catch(error){
                console.log(error);
            }       
    }
 return (
    <div className="container mt-4">
        <div className="row">
            <aside className="col-md-3">
                <Teachersidebar></Teachersidebar>
            </aside>
            <section className="col-md-9">
                <div className="card">
                        <h5 className="card-header">Add Course</h5>
                        <div className="card-body">
                            <form>
                                <div className="mb-3">
                                    <label htmlFor="catregory" className="form-label">Category</label>
                                    <select name="category" onChange={handleChange} className="form-control">
                                        {cats.map((category,index)=>
                                            <option key={index} value={category.id}>{category.title}</option>
                                        )}
                                    </select>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="name" className="form-label">Title</label>
                                    <input type="text"name="title" onChange={handleChange} className="form-control" id="name"/>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="description" className="form-label">Description</label>
                                    <textarea className="form-control"></textarea>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="img" className="form-label">Featured Image</label>
                                    <input type="file" id="img" onChange={handleChange} name="featured_img" className="form-control"/>
                                </div>

                                <div className="mb-3">
                                    <label htmlFor="Technology" className="form-label">Technologies used</label>
                                    <textarea className="form-control" onChange={handleChange} name="techs"></textarea>
    
                                </div>
                                <button type="submit" onClick={submitForm} className="btn btn-primary">submit</button>
                            </form>
                        </div>
                    </div>
            </section>
        </div>
      </div>
 );
}
export default Addcourse
